/// CheckReportFormat names the file RenderCheckReport writes.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum CheckReportFormat {
    Unspecified = 0,
    /// The CheckResults document, as results.Marshal writes it. It holds the findings, skipped rules,
    /// the catalog snapshot, the run's provenance, the producer version and the design's content hash.
    /// It is the durable, machine-readable record of a run, and `agni results` re-renders it.
    ResultsJson = 1,
    /// The self-contained verdict report page, with every rule's considered set, passes included. A
    /// CheckResults document cannot hold it, because that document holds findings and not verdicts.
    Html = 2,
}
impl CheckReportFormat {
    /// String value of the enum field names used in the ProtoBuf definition.
    ///
    /// The values are not transformed in any way and thus are considered stable
    /// (if the ProtoBuf definition does not change) and safe for programmatic use.
    pub fn as_str_name(&self) -> &'static str {
        match self {
            Self::Unspecified => "CHECK_REPORT_FORMAT_UNSPECIFIED",
            Self::ResultsJson => "CHECK_REPORT_FORMAT_RESULTS_JSON",
            Self::Html => "CHECK_REPORT_FORMAT_HTML",
        }
    }
    /// Creates an enum from field names used in the ProtoBuf definition.
    pub fn from_str_name(value: &str) -> ::core::option::Option<Self> {
        match value {
            "CHECK_REPORT_FORMAT_UNSPECIFIED" => Some(Self::Unspecified),
            "CHECK_REPORT_FORMAT_RESULTS_JSON" => Some(Self::ResultsJson),
            "CHECK_REPORT_FORMAT_HTML" => Some(Self::Html),
            _ => None,
        }
    }
}
